//
// Optionally download a cache and normalise a VCF, then annotate it with vepyr
//

include { BCFTOOLS_NORM  } from 'nf-core/bcftools/norm'
include { HUGGINGFACE_DOWNLOAD } from 'nf-core/huggingface/download'
include { VEPYR_ANNOTATE } from 'nf-core/vepyr/annotate'

workflow VCF_ANNOTATE_VEPYR {
    take:
    ch_vcf            // channel: [ val(meta), path(vcf), path(tbi) ] (tbi optional, pass [])
    ch_cache          // channel: [ val(meta2), path(cache) ] (value channel; pass [[], []] when val_hf_repo is set)
    ch_fasta          // channel: [ val(meta3), path(fasta), path(fai), path(gzi) ] (value channel; gzi only for a bgzip FASTA, else [])
    val_cache_version // value:   integer, or [] to skip the cache version check
    ch_plugin_cache   // channel: [ val(meta4), path(plugin_cache) ] (optional, pass [ [], [] ])
    val_normalize     // value:   boolean, run BCFTOOLS_NORM before annotation
    val_hf_repo       // value:   Hugging Face dataset ID, or '' / [] to use ch_cache

    main:
    def ch_cache_value = ch_cache instanceof List ? channel.value(ch_cache) : ch_cache

    if (val_hf_repo) {
        def hf_repo = val_hf_repo.startsWith('datasets/') ? val_hf_repo : "datasets/${val_hf_repo}"
        // A value channel shares one cache download across all input samples.
        HUGGINGFACE_DOWNLOAD(channel.value([
            [id: val_hf_repo.tokenize('/').last()],
            hf_repo,
            [],
        ]))
        ch_annotate_cache = HUGGINGFACE_DOWNLOAD.out.output
            .combine(ch_cache_value.map { _meta, cache ->
                if (cache) {
                    error("VCF_ANNOTATE_VEPYR: set either ch_cache or val_hf_repo, not both.")
                }
                true
            })
            .map { meta, cache, _no_local_cache -> [meta, cache] }
            .first()
    }
    else {
        ch_annotate_cache = ch_cache_value.map { meta, cache ->
            if (!cache) {
                error("VCF_ANNOTATE_VEPYR: no cache given, set ch_cache or val_hf_repo.")
            }
            [meta, cache]
        }
    }

    ch_annotate_input = ch_vcf

    if (val_normalize) {
        BCFTOOLS_NORM(
            ch_vcf,
            ch_fasta.map { meta, fasta, _fai, _gzi -> [meta, fasta] },
        )

        // Without --write-index bcftools/norm emits no index; VEPYR_ANNOTATE then
        // builds one.
        ch_annotate_input = BCFTOOLS_NORM.out.vcf
            .join(BCFTOOLS_NORM.out.index, failOnDuplicate: true, remainder: true)
            .map { meta, vcf, index -> [meta, vcf, index ?: []] }
    }

    VEPYR_ANNOTATE(
        ch_annotate_input,
        ch_annotate_cache,
        ch_fasta,
        val_cache_version,
        ch_plugin_cache,
    )

    ch_vcf_tbi = VEPYR_ANNOTATE.out.vcf.join(VEPYR_ANNOTATE.out.tbi, failOnDuplicate: true, failOnMismatch: true)

    emit:
    vcf_tbi = ch_vcf_tbi // channel: [ val(meta), path(vcf), path(tbi) ]
}

nextflow_workflow {

    name "Test Subworkflow VCF_ANNOTATE_VEPYR"
    script "../main.nf"
    workflow "VCF_ANNOTATE_VEPYR"

    tag "subworkflows"
    tag "subworkflows_nfcore"
    tag "subworkflows/vcf_annotate_vepyr"
    tag "bcftools"
    tag "bcftools/norm"
    tag "vepyr"
    tag "vepyr/annotate"
    tag "huggingface"
    tag "huggingface/download"

    test("homo_sapiens - vcf - normalise") {

        config "./nextflow.config"

        // raw.githubusercontent.com serves blobs, not directory trees, so the cache
        // is published as an archive and extracted here.
        def cache
        setup {
            // params.modules_testdata_base_path is null outside the process string, so use the same env var and default as tests/config/nf-test.config
            def modules_testdata_base_path = System.getenv('NXF_MODULES_TESTDATA_BASE') ?: 'https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/'
            cache = extract(modules_testdata_base_path + 'genomics/homo_sapiens/vepyr/cache.tar.gz').resolve('cache')
            run("BCFTOOLS_NORM", alias: "BCFTOOLS_JOIN_MULTIALLELICS") {
                script "modules/nf-core/bcftools/norm/main.nf"
                process {
                    """
                    input[0] = channel.of([
                        [ id:'joined' ],
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/vepyr/input.vcf.gz', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/vepyr/input.vcf.gz.tbi', checkIfExists: true)
                    ])
                    input[1] = channel.value([
                        [ id:'GRCh38' ],
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/vepyr/reference.fa.gz', checkIfExists: true)
                    ])
                    """
                }
            }
        }

        when {
            workflow {
                """
                input[0] = BCFTOOLS_JOIN_MULTIALLELICS.out.vcf.map { _meta, vcf -> [ [ id:'test' ], vcf, [] ] }
                input[1] = [ [ id:'116_GRCh38_ensembl' ], file('${cache}') ]
                input[2] = channel.value([
                    [ id:'GRCh38' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/vepyr/reference.fa.gz', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/vepyr/reference.fa.gz.fai', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/vepyr/reference.fa.gz.gzi', checkIfExists: true)
                ])
                input[3] = 116
                input[4] = [[], []]
                input[5] = true
                input[6] = ''
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success },
                { assert !workflow.trace.tasks().any { it.name.contains('HUGGINGFACE_DOWNLOAD') } },
                { assert workflow.out.vcf_tbi.size() == 1 },
                { assert file(workflow.out.vcf_tbi[0][2]).exists() },
                { assert workflow.trace.tasks().collect { it.name.tokenize(' ')[0] }.toSet().containsAll(['VCF_ANNOTATE_VEPYR:BCFTOOLS_NORM', 'VCF_ANNOTATE_VEPYR:VEPYR_ANNOTATE']) },
                // Setup joins input.vcf.gz back into 986 records, 14 of them multiallelic.
                { assert path(workflow.out.vcf_tbi[0][1]).vcf.variants.size() == 1000 },
                { assert path(workflow.out.vcf_tbi[0][1]).vcf.variants.every { it.alternateAlleles.size() == 1 } },
                { assert snapshot(
                    workflow.out.vcf_tbi.collect { meta, vcf, tbi -> [ meta, file(vcf).name + ",variantsMD5:" + path(vcf).vcf.variantsMD5, file(tbi).name ] }
                ).match() }
            )
        }
    }

